    private static async Task RunTestMigrationsAsync(
        IServiceProvider services, IReadOnlyList<IWallowModule> enabledModules)
    {
        await using AsyncServiceScope scope = services.CreateAsyncScope();
        IServiceProvider sp = scope.ServiceProvider;

        // Core module contexts (Identity) migrate first and sequentially — seeding elsewhere
        // depends on Identity's schema existing. The two auditing contexts belong to no module
        // (see IWallowModule.DbContextTypes) and are migrated explicitly alongside them, in the
        // same Identity-then-Audit-then-AuthAudit order this method has always used.
        foreach (IWallowModule module in enabledModules.Where(m => m.IsCore))
        {
            foreach (Type contextType in module.DbContextTypes)
            {
                await MigrateContextAsync(sp, contextType);
            }
        }

        await sp.GetRequiredService<AuditDbContext>().Database.MigrateAsync();
        await sp.GetRequiredService<AuthAuditDbContext>().Database.MigrateAsync();

        // Feature module contexts run in parallel. No probe needed: enabledModules is already the
        // exact set AddWallowModules called AddServices for, so every context here is guaranteed
        // registered in this same services collection (MigrateIfRegistered's sp.GetService probe
        // existed only because the old code did not know the enabled set going in).
        List<Task> featureMigrations =
        [
            .. enabledModules
                .Where(m => !m.IsCore)
                .SelectMany(m => m.DbContextTypes)
                .Select(contextType => MigrateContextAsync(sp, contextType)),
        ];

        await Task.WhenAll(featureMigrations);
    }

    private static Task MigrateContextAsync(IServiceProvider sp, Type contextType) =>
        ((DbContext)sp.GetRequiredService(contextType)).Database.MigrateAsync();

