// Testid derivation for the repo's {page}-{element} convention (.claude/rules/E2E.md).
// Derived, not hand-written: testIdPrefix="inquiry" + field "projectType" produces
// "inquiry-project-type" / "inquiry-project-type-error". A field's testId prop
// overrides the derivation so migrated forms keep their E2E ids byte-identical.
const kebab = (name) =>
  name.replace(/[A-Z]/gu, (c) => "-" + c.toLowerCase()).replace(/\./gu, "-");

export function fieldTestId(prefix, fieldName) {
  return prefix + "-" + kebab(fieldName);
}

export function fieldErrorTestId(prefix, fieldName) {
  return fieldTestId(prefix, fieldName) + "-error";
}
```
(Use real TypeScript template literals and type annotations `(prefix: string, fieldName: string): string` when writing the actual file -- the plus-concatenation above is just to survive this text field; template-literal form is preferred: return the prefix and kebab-cased name joined with a hyphen, same for the error id joined with "-error".)

